// Ask the hub: answers questions from the people hub's own content.
//
// POST { question: string, history?: { role: 'user' | 'assistant', content: string }[] }
// Streams the model's reply back as OpenAI-style server-sent events.
//
// Secrets (supabase secrets set ...):
//   OPENROUTER_API_KEY  required
//   OPENROUTER_MODEL    the OpenRouter model slug to use (defaults to openrouter/auto)
//   ALLOWED_ORIGINS     comma-separated origins allowed to call this (defaults to *)
//
// content.json is generated by `npm run content` (scripts/build-content-index.mjs);
// redeploy the function after changing hub pages.
import content from './content.json' with { type: 'json' };

const OPENROUTER_URL = 'https://openrouter.ai/api/v1/chat/completions';
const MAX_QUESTION = 1000;
const MAX_HISTORY = 6;
const MAX_TURN = 4000;
const WINDOW_MS = 10 * 60 * 1000;
const MAX_REQUESTS = 30;

// Best-effort limit per instance; enough to stop a runaway loop.
const recent = new Map<string, number[]>();

function rateLimited(key: string) {
  const now = Date.now();
  const hits = (recent.get(key) ?? []).filter((t) => now - t < WINDOW_MS);
  hits.push(now);
  recent.set(key, hits);
  return hits.length > MAX_REQUESTS;
}

function corsHeaders(origin: string | null): Record<string, string> {
  const allowed = (Deno.env.get('ALLOWED_ORIGINS') ?? '*').split(',').map((o) => o.trim());
  const allow = allowed.includes('*') ? '*' : origin && allowed.includes(origin) ? origin : allowed[0];
  return {
    'Access-Control-Allow-Origin': allow,
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    Vary: 'Origin',
  };
}

function reply(body: unknown, status: number, cors: Record<string, string>) {
  return new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });
}

type Turn = { role: 'user' | 'assistant'; content: string };

function isTurn(value: unknown): value is Turn {
  const turn = value as Turn;
  return (
    typeof turn === 'object' &&
    turn !== null &&
    (turn.role === 'user' || turn.role === 'assistant') &&
    typeof turn.content === 'string' &&
    turn.content.trim().length > 0
  );
}

Deno.serve(async (req) => {
  const cors = corsHeaders(req.headers.get('origin'));
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return reply({ error: 'Use POST.' }, 405, cors);

  const caller = req.headers.get('x-forwarded-for')?.split(',')[0].trim() ?? 'unknown';
  if (rateLimited(caller)) {
    return reply({ error: 'Lots of questions at once. Try again in a few minutes.' }, 429, cors);
  }

  let body: { question?: unknown; history?: unknown };
  try {
    body = await req.json();
  } catch {
    return reply({ error: 'Send the question as JSON.' }, 400, cors);
  }

  const question = typeof body.question === 'string' ? body.question.trim() : '';
  if (!question) return reply({ error: 'Ask a question.' }, 400, cors);
  if (question.length > MAX_QUESTION) return reply({ error: 'That question is too long. Keep it under 1,000 characters.' }, 400, cors);

  const history = (Array.isArray(body.history) ? body.history : [])
    .filter(isTurn)
    .slice(-MAX_HISTORY)
    .map((turn) => ({ role: turn.role, content: turn.content.slice(0, MAX_TURN) }));

  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
  if (!apiKey) return reply({ error: 'Ask the hub isn’t set up yet.' }, 503, cors);
  const model = Deno.env.get('OPENROUTER_MODEL') ?? 'openrouter/auto';

  const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Australia/Melbourne' }).format(new Date());
  const system = `${content.instructions.replace('{today}', today)}\n\n# Hub content\n\n${content.content}`;
  // Anthropic models on OpenRouter can cache the long, unchanging hub content between questions.
  const systemMessage = model.startsWith('anthropic/')
    ? { role: 'system', content: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }] }
    : { role: 'system', content: system };

  const upstream = await fetch(OPENROUTER_URL, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': Deno.env.get('SITE_URL') ?? 'https://halfdome.com.au',
      'X-Title': 'Half Dome People Hub',
    },
    body: JSON.stringify({
      model,
      stream: true,
      temperature: 0.2,
      max_tokens: 700,
      messages: [systemMessage, ...history, { role: 'user', content: question }],
    }),
  });

  if (!upstream.ok || !upstream.body) {
    console.error('OpenRouter error', upstream.status, await upstream.text().catch(() => ''));
    return reply({ error: 'Ask the hub is unavailable right now. Try again soon.' }, 502, cors);
  }

  return new Response(upstream.body, {
    headers: { ...cors, 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache' },
  });
});
